INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_121', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-1-2' AND is_deleted = false LIMIT 1), 'status-codes-quiz', 'What does this status tell the client?', 'Two pieces of evidence from the status audit: a learner probing draft course ids, and the queued submission that the mobile app showed as "0 of 0 tests passed".', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
