-- challenge chal_coding_adp_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_122', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-1-2' AND is_deleted = false LIMIT 1), 'choose-status-code', 'Choose the status code and the headers', 'Every CodeDev API handler reports a business outcome, and one function turns the HTTP method and that outcome into the status code and the headers the client needs. Write chooseResponse(method, outcome) returning { status, headers } with exactly this table (outcome.kind -> status, headers): ok -> 204 when the method is DELETE, 200 otherwise, no headers; created -> 201, with Location: outcome.location only when the method is POST (a PUT that creates has no Location); accepted -> 202 with Location: outcome.location (the status resource to poll); already_exists -> 200; validation_failed -> 400; rule_violated -> 422; unauthenticated -> 401 with WWW-Authenticate: Bearer realm="codedev"; forbidden -> 403, or 404 when outcome.hidden is true (the caller may not learn that the resource exists); not_found -> 404; version_conflict -> 409; payment_required -> 402; rate_limited -> 429 with Retry-After; gone -> 410; dependency_down -> 503 with Retry-After; method_not_allowed -> 405 with Allow; any other kind (kinds are case-sensitive) -> 500 with no headers. Rules: compare the method case-insensitively ("delete" is DELETE). Retry-After is outcome.retryAfterSeconds written as a string when it is a number that is a whole number >= 0, otherwise "60". Allow lists outcome.allowed uppercased, without duplicates, in the order GET, HEAD, POST, PUT, PATCH, DELETE, OPTIONS, joined with ", "; methods not in that list are dropped, and a missing or empty list gives Allow: "". A created outcome for a POST, or any accepted outcome, without a non-empty location string is a handler bug: 500 with no headers. Header names are exactly Location, Retry-After, Allow and WWW-Authenticate; a response without headers has headers {}. The test runner reads { cases: [{ method, outcome }] } as JSON and prints the list of { status, headers }.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
