-- challenge chal_quiz_adp_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_131', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-1-3' AND is_deleted = false LIMIT 1), 'error-contract-quiz', 'Three error shapes and one banner', 'Two pieces of evidence from the error contract incident: the three error bodies the mobile app received, and two answers to the same invalid request.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131'), 'Mobile app 3.6 handles every error response with:

const body = await res.json();
showBanner(String(body.message));

The API returned these three bodies the same afternoon:

(A) POST /enrollments -> 400
{"statusCode":400,"message":["email must be an email","courseId should not be empty"],"error":"Bad Request"}

(B) POST /enrollments -> 409
{"type":"https://api.codedev.test/problems/already-enrolled","title":"Already enrolled","status":409,"detail":"You are already enrolled in crs_42."}

(C) POST /orders -> 402
{"error":{"code":"CARD_DECLINED","msg":"The card was declined."}}

Statement: "The banner shows the text undefined for (B) and (C), and for (A) it shows both validation messages joined by a comma."', 'single_choice'::question_type, 'True. Only body (A), Nest''s default validation response, has a top-level message member, and it is an array: String([...]) joins the elements with commas. Body (B) is RFC 9457 problem+json, which has title and detail but no message; body (C) nests its text under error.msg. For both, body.message is undefined and String(undefined) is the text "undefined". The misconception is that the client bug is in the app: the app can only read one shape, and the API sent three. Patching the app with a fallback chain moves the problem to every other client; one contract on the server fixes it for all of them.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131'), 'The same invalid request, sent twice, one minute apart:

POST /courses  {"title":"","price":-1}

First answer (400):
"details":[{"field":"title","code":"required","message":"validation.required"},{"field":"price","code":"out_of_range","message":"validation.out_of_range"}]

Second answer (400):
"details":[{"field":"price","code":"out_of_range","message":"validation.out_of_range"},{"field":"title","code":"required","message":"validation.required"}]

The admin app shows details[0].message at the top of the form, and the API''s contract tests compare error bodies with stored snapshots.

Statement: "Both answers contain the same field errors, so their order cannot break the admin app or the tests."', 'single_choice'::question_type, 'False. The admin app shows details[0], so the same mistake shows a different headline on each attempt, and a snapshot test of the body passes or fails depending on which order the validators finished in: a flaky test. The order is part of what clients observe, and anything clients observe becomes part of the contract whether you meant it or not. The fix is to sort details in one place, for example by field and then code, so the same input always gives the same body. The misconception is that a list with the same elements is the same answer; for clients and tests, a different order is a different response.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_adp_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_132', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-1-3' AND is_deleted = false LIMIT 1), 'error-contract-formatter', 'One formatter for every error', 'The CodeDev API answered errors in three shapes, and the mobile app showed "undefined" for half of them. Write formatError(thrown, ctx), the one function every error goes through, returning { status, headers, body } where headers is exactly { "Content-Type": "application/problem+json" } and body is { type, title, status, code, message, details, traceId, instance }. Sources: an AppError (domain error) uses its code, status and message and its details list; a ValidationFailed uses status 400, code "VALIDATION_FAILED", message "request.invalid" and its errors list as details; an HttpError (framework) uses its status, code "HTTP_<status>" (for example "HTTP_404") and its message, with no details; anything else (an Error, a string, null, a plain object that only looks like an AppError) is status 500 with code "INTERNAL_ERROR". An AppError or HttpError whose status is not a whole number from 400 to 599 is treated as anything else. When the status is 500 or more, message is "server.error" and details is [] (never the thrown message or stack); an AppError keeps its code. Messages are message keys that clients translate: pass them through exactly, without trimming or changing case. Details: keep only entries that are objects with a string field; output exactly { field, code, message } (a code or message that is not a string becomes "") and never other members such as the rejected value; sort by field, then by code, comparing strings with < and >; keep at most MAX_DETAILS (10), and when more are left keep the first 10 and append the marker { field: "*", code: "DETAILS_TRUNCATED", message: "details.truncated" }. type is "https://api.codedev.test/problems/" plus the code in lowercase with every "_" replaced by "-". title is TITLES[status] from the starter, or "Error" when the status is not in the table. traceId is ctx.traceId when it is a non-empty string, otherwise "unknown"; instance is ctx.path. The test runner rebuilds each thrown value from JSON, throws it, passes what it catches to formatError and prints the list of responses.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_132'), 1, 'Which three decisions does the formatter make for every error, and in what order? First where it came from (status and code), then whether it is the server''s fault (what may be shown), and only then how the details look.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_132'), 2, 'Look at instanceof for the three classes, and at the place where a 5xx status overrides what the source said. For details, the work is a filter (objects with a string field), a map to exactly three members, a sort with a second comparison for ties, and a slice with the marker appended only when something was cut off.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_132'), 3, 'A similar formatter for the leaderboard''s warnings: entries { user, rule, text, score } are sorted by user, then rule, keep only { user, rule, text }, and at most 3 are shown. For users ["lin", "an", "an", "bo", "cy"] with rules ["b", "z", "a", "x", "y"] the result is an/a, an/z, bo/x, then a { user: "*" } marker because cy and lin were cut. A thrown string has no status, so it takes the generic server branch, like a TypeError would.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
