-- challenge chal_quiz_adp_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_211', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-1' AND is_deleted = false LIMIT 1), 'cursor-pagination-quiz', 'Where does page 2 start?', 'Two keyset pagination implementations of GET /courses: a cursor that holds only the timestamp, and a last page detected by counting rows.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211'), '-- page 1 (no cursor)
SELECT id, title, published_at FROM catalog.courses
ORDER BY published_at DESC LIMIT 3;

-- page 2: the cursor holds only published_at of the last row of page 1
SELECT id, title, published_at FROM catalog.courses
WHERE published_at < $1
ORDER BY published_at DESC LIMIT 3;

Rows in the table (newest first):
 id | published_at
 31 | 2026-10-01 09:00:00+00
 30 | 2026-10-01 08:00:00+00
 29 | 2026-10-01 08:00:00+00
 28 | 2026-10-01 08:00:00+00
 27 | 2026-10-01 07:00:00+00

Page 1 returned ids 31, 30, 29, so page 2 runs with $1 = ''2026-10-01 08:00:00+00''.

Statement: "Course 28 is never returned: not on page 1, and not on page 2 or any later page."', 'single_choice'::question_type, 'True. Page 2 asks for published_at strictly before 08:00:00, so every row that shares 08:00:00 with the last row of page 1 is excluded, and course 28 is one of them. Switching to <= would bring 28 back but also repeat 30 and 29. The fix is a cursor that holds the full position (published_at, id) and the row comparison WHERE (published_at, id) < ($1, $2) with ORDER BY published_at DESC, id DESC. The misconception is that a timestamp is precise enough to be unique: batch imports, seeds and coarse clocks produce ties all the time.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211'), '// CoursesService.list (NestJS), 40 published courses in the catalog
const rows = await this.repo.page(after, limit); // ... ORDER BY published_at DESC, id DESC LIMIT $3  ($3 = limit)
const last = rows[rows.length - 1];
return {
  data: rows,
  next_cursor: rows.length === limit ? encodeCursor(last) : null,
};

The mobile app requests GET /courses?limit=20 and follows next_cursor until it is null.

Statement: "The response to the app''s second request has next_cursor null, so the app stops after two requests."', 'single_choice'::question_type, 'False. The second page holds courses 21-40, so rows.length === limit and the service returns a cursor. The app makes a third request, which returns an empty page with next_cursor null. A full page does not prove that more rows exist. Ask the database for limit + 1 rows, return the first limit, and set next_cursor only when the extra row came back. The misconception is that "page is full" and "there is a next page" mean the same thing; they differ exactly when the total is a multiple of the limit.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_adp_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_212', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-1' AND is_deleted = false LIMIT 1), 'cursor-pagination-courses', 'Cursor pagination for GET /courses', 'GET /courses on the CodeDev catalog is moving from page numbers to cursor (keyset) pagination, because the mobile app shows repeated and missing courses while instructors publish. Write encodeCursor, decodeCursor and listCourses in TypeScript. Order: published_at, then id as the tie-break, both in the direction of `order` ("desc" = newest first, the default; "asc" = oldest first). Query values arrive as strings or are missing, and are checked in this order, the first failure being the result: limit - missing -> 20; a whole number from 1 to 100 -> that many; above 100 -> 100; anything else ("0", "-5", "2.5", "ten", "") -> { status: 400, code: "invalid_limit" }. order - missing -> "desc"; "asc" or "desc"; anything else -> 400 invalid_order. cursor - missing -> the first page; otherwise it must decode to a cursor made for the same order, else 400 invalid_cursor. A cursor is the base64url text (Buffer.from(json).toString("base64url"), no "=" padding) of JSON.stringify({ v: 1, o: order, k: [published_at, id] }) for the last course on the page, keys in that order. decodeCursor returns null unless the text uses only A-Z a-z 0-9 - _, the JSON parses to an object, v is 1, o is "asc" or "desc", k has exactly two items, k[0] is a timestamp written like "2026-10-01T08:00:00Z" and k[1] is a whole number >= 1. A successful response is { status: 200, data, next_cursor }: data holds the courses that come after the cursor position in the chosen order (from the start without a cursor), at most limit of them; next_cursor is the cursor of the last course on the page when more courses follow it, and null when the page reaches the end of the list. published_at values all have the same format, so comparing them as strings compares the times. The test runner keeps the table, publishes courses between requests, follows next_cursor ("$next" in the input), and prints the ids of each page, the cursor, and at the end of the list how many courses the pages returned and which ones came twice.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_212'), 1, 'Page 2 starts right after the last course of page 1. When several courses share that course''s published_at, which values identify the position exactly, and what must the next query compare to continue from there?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_212'), 2, 'Use one comparison for both the sort and the "after the cursor" filter: published_at first, id second, and the sign flipped for desc. For next_cursor, think about how to know that one more course exists without a second query: you are allowed to read more than limit rows.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_212'), 3, 'A similar case on other data: a leaderboard ordered by score desc, then user_id desc, limit 2, rows (90, 7), (90, 5), (90, 3), (80, 9). Page 1 is users 7 and 5, cursor position (90, 5). Page 2 is every row strictly after (90, 5) in that order: (90, 3) because the score is equal and 3 < 5, then (80, 9). Reading 3 rows for a limit of 2 tells you whether a page 3 exists. A cursor with version 2, or one made for asc and sent with desc, is rejected before any row is read.');
