-- challenge chal_quiz_adp_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_221', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-2' AND is_deleted = false LIMIT 1), 'offset-pagination-quiz', 'Why did the course show up twice?', 'Evidence from the AI-written offset pagination of GET /courses: a request log with a course published between two pages, and two queries that return tied rows in a different order.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221'), 'SQL run by the AI''s code (size 20):
SELECT id, title, published_at FROM catalog.courses
ORDER BY published_at DESC LIMIT 20 OFFSET ($2 - 1) * 20;

API log (one learner, one instructor):
10:00:05 GET /courses            200  data[19].id = 412 (Redis Patterns)
10:00:20 POST /courses/388/publish 200  (instructor, published_at = 10:00:20)
10:00:31 GET /courses?cursor=eyJwYWdlIjoyfQ  200  data[0].id = 412 (Redis Patterns)

A reviewer proposes: change the ORDER BY to published_at DESC, id DESC and keep the OFFSET.

Statement: "With the reviewer''s change, the 10:00:31 request no longer starts with Redis Patterns."', 'single_choice'::question_type, 'False. The id tie-break makes the order of tied rows deterministic, but this duplicate has another cause: course 388 was published at 10:00:20, so it is now first in the list and every other course moved down one position. OFFSET 20 skips 20 rows of the new list, the first 19 of page 1 plus the new course, so row 21 is again Redis Patterns. Only a cursor that remembers the position (published_at, id) of the last row instead of a row count is immune to inserts above it. The misconception is that one fix (a unique order) solves both problems; ties and shifting offsets are two different failures.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221'), 'A batch import published 6 courses at exactly 2026-10-20 07:00:00+00. The same query runs twice, one minute apart, with no writes in between:

SELECT id FROM catalog.courses
WHERE published_at = ''2026-10-20 07:00:00+00''
ORDER BY published_at DESC;

run 1: 501, 502, 503, 504, 505, 506
run 2: 504, 501, 502, 506, 503, 505   (a parallel sequential scan was used this time)

Statement: "Both results are correct answers to this query, so with OFFSET a learner can see some of these courses twice and miss others."', 'single_choice'::question_type, 'True. ORDER BY published_at says nothing about the order of rows with equal published_at, and PostgreSQL may return ties in any order: it depends on the plan (index scan, sort, parallel workers) and on where the rows are stored. When page 1 and page 2 cut through a group of ties and the two queries order the group differently, OFFSET returns some rows twice and never returns others. The fix is a total order: add a unique column (id) as the last sort key, and paginate with a keyset cursor on the same columns. The misconception is that the database returns rows in insertion order unless told otherwise.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_adp_222 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_222', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-2' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-offset-pagination', 'Spot the AI Mistake: offset pagination that skips & repeats rows', 'The mobile team asked an AI assistant: "Add pagination to GET /courses. Response: { data, next_cursor }; the app sends next_cursor back as ?cursor= and stops when it is null. ?size= is optional: default 20, at most 100. Answer 400 with { code } for a bad size or cursor. Newest courses first." Its code (listCourses in the starter, with the SQL it runs in a comment) passed the endpoint tests and was merged. Since then learners report the same course twice while scrolling the catalog, and support found published courses that never appear in the app. It happens when instructors publish while someone scrolls, and after a batch import that published many courses in the same second. Fix listCourses so that a learner who starts at the first page and follows next_cursor to the end sees, exactly once and newest first (published_at descending, then id descending), every course that existed when they started, whatever is published in between and whatever order the table returns its rows in. Keep the contract: the response shape { data, next_cursor }, the size rules and the 400 codes stay as they are, and next_cursor is null on the last page. A cursor the API cannot read gets 400 invalid_cursor, and that includes the cursors issued by the current version, so that the app reloads the list from the start after the deploy. The format of your cursor is up to you. The public tests pass on the AI''s code; the hidden tests publish courses between requests and use courses with the same publish time.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222'), 1, 'The cursor tells the server where the learner stopped. In the AI''s code, is that a place in the data (a course) or a count of rows from the top of the list? What happens to a count when a course is published above the learner, or when tied rows come back in another order?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222'), 2, 'Look at the ORDER BY in the comment and at what encodeCursor stores. Is published_at unique? What would the next request need to know to continue right after the last course it returned, even if new rows appear before it?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222'), 3, 'A similar case: a support inbox listed newest first, tickets (10:00, #41), (10:00, #40), (09:58, #39), two per page. With OFFSET 2, a new ticket arriving before page 2 pushes #40 down and page 2 starts with #40 again. Storing the position instead - after (10:00, #40) - the next query is WHERE (created_at, id) < (''10:00'', 40) ORDER BY created_at DESC, id DESC, which returns #39 whatever arrived in between.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222');
