8,107,106,105,104,103] next=yes\nGET -> 200 [102,101,100] next=null\nend of list: duplicates none; never returned none\nGET -> 200 [122,121,120,119,118,117,116,115,114,113,112,111,110,109,108,107,106,105,104,103,102,101,100] next=null\nend of list: duplicates none; never returned none\nGET -> 400 invalid_size\nGET -> 400 invalid_size\nGET -> 400 invalid_cursor"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_222'), 'An instructor publishes a course between page 1 and page 2: nothing repeats', '{"rows":[{"id":1,"title":"HTTP Fundamentals","published_at":"2026-10-01T08:00:00Z"},{"id":2,"title":"SQL Basics","published_at":"2026-10-01T08:15:00Z"},{"id":3,"title":"TypeScript Foundations","published_at":"2026-10-01T08:30:00Z"},{"id":4,"title":"React Hooks","published_at":"2026-10-01T08:45:00Z"},{"id":5,"title":"Node Streams","published_at":"2026-10-01T09:00:00Z"},{"id":6,"title":"Redis Patterns","published_at":"2026-10-01T09:15:00Z"},{"id":7,"title":"API Design for Production","published_at":"2026-10-01T09:30:00Z"},{"id":8,"title":"Docker Basics","published_at":"2026-10-01T09:45:00Z"}],"steps":[{"get":{"size":"3"}},{"insert":[{"id":9,"title":"Vue Basics","published_at":"2026-10-01T11:20:00Z"}]},{"get":{"size":"3","cursor":"$next"}},{"insert":[{"id":10,"title":"Svelte Basics","published_at":"2026-10-01T11:30:00Z"},{"id":11,"title":"Go Concurrency","published_at":"2026-10-01T11:40:00Z"}]},{"get":{"size":"3","cursor":"$next"}}]}', '"GET -> 200 [8,7,6] next=yes\ninsert 9\nGET -> 200 [5,4,3] next=yes\ninsert 10,11\nGET -> 200 [2,1] next=null\nend of list: duplicates none; never returned none"', 3, false, true, 3),
