-- challenge chal_quiz_adp_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_231', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-3' AND is_deleted = false LIMIT 1), 'filter-sort-quiz', 'What can reach the ORDER BY?', 'Two pieces of evidence from the CodeDev list endpoints: a sort parameter checked with a regular expression, and two search requests that differ only in how they encode a plus sign.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231'), '// list-query.helper.ts, used by GET /courses and GET /courses/:id/learners
const desc = sort.startsWith("-");
const column = desc ? sort.slice(1) : sort;
if (!/^[a-z_]+$/.test(column)) throw new BadRequestException("invalid sort");
return this.db.query(
  `SELECT * FROM ${table} WHERE course_id = $1 ORDER BY ${column} ${desc ? "DESC" : "ASC"} LIMIT 50`,
  [courseId],
);

Statement: "Because only lowercase letters and underscores can reach ORDER BY, GET /courses/42/learners?sort=password_hash is rejected with 400."', 'single_choice'::question_type, 'False. password_hash is made of lowercase letters and an underscore, so it passes the regular expression and the learners come back ordered by their password hash, which leaks information about the hashes and shows the column exists. The regex blocks SQL injection syntax, but it checks the shape of the input, not whether the column may be used. Column names cannot be bound as $n parameters, so the safe design is an allowlist per endpoint (title, rating, price, published_at) that maps the request to a fixed column; anything else is a 400. The SELECT * is a second problem: the list returns every column of the table. The misconception is that "no injection possible" means "safe".', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231'), 'Two requests from the catalog search box, and the value the API logged after decoding the query string:

GET /courses?q=c%2B%2B      -> q = "c++"
GET /courses?q=c++          -> q = "c  "

Statement: "The two requests search for different text, because in a query string a literal + is decoded as a space."', 'single_choice'::question_type, 'True. In application/x-www-form-urlencoded query strings, which browsers produce for forms and URLSearchParams produces too, + stands for a space and a real plus sign must be sent as %2B. The second request therefore searches for "c" followed by two spaces, and after trimming only for "c". A server that only calls decodeURIComponent would keep + as +, and disagree with every client that encodes spaces as +. The client should build query strings with URLSearchParams or encodeURIComponent, and the server should decode + as a space before percent-decoding. The misconception is that + in a URL is always a literal plus.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_adp_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_232', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-2-3' AND is_deleted = false LIMIT 1), 'safe-filter-sort-plan', 'Parse filters and sorts into a safe query plan', 'Incident: GET /courses/42/learners?sort=password_hash returned learners ordered by their password hash, because a shared list helper put the sort parameter into ORDER BY. Every CodeDev list endpoint will now parse its query string into a query plan with an allowlist, and only the plan reaches the SQL. Write parseListQuery(query) for GET /courses: query is the raw query string without "?"; return { status: 200, plan: { filters, sort, q } } or { status: 400, errors } with every problem found. FILTERS, SORTABLE, MAX_LIST (10) and MAX_SORT (3) are given in the starter; do not change them. Rules: (1) Split on "&", skip empty parts, split each part at the first "=" (no "=" -> value ""). Decode name and value: "+" is a space, then percent-decoding; if either fails -> malformed percent-encoding in "<raw part>". (2) The decoded name must be field or field[op] (lowercase letters and "_"; op lowercase letters) -> else invalid parameter name "<name>"; a name seen before -> duplicate parameter "<name>". (3) limit and cursor belong to pagination: skip them. q: trimmed value of 1-100 characters, else "q" must be 1-100 characters; no q -> null. (4) sort: split on ","; more than 3 items -> too many sort fields (max 3); each item is a field with an optional leading "-" (descending); field not in SORTABLE -> cannot sort by "<field>"; a field twice -> "<field>" appears twice in sort. The plan''s sort ends with { field: "id", dir: <dir of the last item> }; no sort parameter -> published_at desc, then id desc. (5) Anything else is a filter: split the value on ","; field not in FILTERS -> unknown filter "<field>"; the operator is the one in brackets, else eq for one value and in for several; operator not in the field''s ops -> operator "<op>" is not allowed on "<field>"; several values with an operator other than in -> "<name>" takes one value; more than 10 values -> too many values for "<field>" (max 10); then each value left to right, the first bad one -> invalid value "<value>" for "<field>": expected <expected of the rule>. Value types: enum = one of the rule''s values, string = 1 to maxLength characters, integer = digits only and at most Number.MAX_SAFE_INTEGER (a number), number = digits with an optional "." and digits, from min to max (a number), boolean = "true" or "false" (a boolean). A filter is { field, op, value } with the converted value, or the array of values for in. Each parameter gives at most one error (the first failed check in that order); errors and filters follow the order of the query string. The test runner prints one JSON result per query.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 1, 'Which parts of the request end up inside the SQL text itself rather than as a $1 parameter, and how can your parser guarantee that those parts are only strings you wrote yourself?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 2, 'Go parameter by parameter in a fixed order: decode (decodeURIComponent throws a URIError on a bad sequence, and "+" must become a space before it runs), check the name, check duplicates, then route to q, sort or a filter. Inside a filter: field, operator, number of values, then each value. Stop at the first problem of that parameter, but keep going with the next parameter.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 3, 'A similar case on a blog API whose allowlist is { tag: string, eq/in } and whose sortable fields are [date]: ?tag=a%2Bb&tag[ne]=x&order=-date&sort=date,-date. tag decodes to "a+b" (a real plus, %2B), so it is an eq filter. tag[ne] is a different name from tag, so it is not a duplicate, but ne is not one of tag''s operators. order is not sort, so it is an unknown filter. sort lists date twice. Three errors, in that order.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
