INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'The catalog query from the API docs becomes a plan', '{"queries":["level=beginner,intermediate&price[lte]=200000&sort=-rating,title&q=react"]}', '{"status":200,"plan":{"filters":[{"field":"level","op":"in","value":["beginner","intermediate"]},{"field":"price","op":"lte","value":200000}],"sort":[{"field":"rating","dir":"desc"},{"field":"title","dir":"asc"},{"field":"id","dir":"asc"}],"q":"react"}}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'The incident: sort=password_hash and an unknown filter are rejected with every error listed', '{"queries":["sort=password_hash&role=admin&level=beginner&limit=20"]}', '{"status":400,"errors":["cannot sort by \"password_hash\"","unknown filter \"role\""]}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'Percent-encoding and + decode before parsing: brackets, spaces, c++ and Vietnamese text', '{"queries":["q=+c%2B%2B+v%C3%A0+node+js+&price%5Bgte%5D=99000&category=web%20frontend,mobile&is_free=false&cursor=abc"]}', '{"status":200,"plan":{"filters":[{"field":"price","op":"gte","value":99000},{"field":"category","op":"in","value":["web frontend","mobile"]},{"field":"is_free","op":"eq","value":false}],"sort":[{"field":"published_at","dir":"desc"},{"field":"id","dir":"desc"}],"q":"c++ và node js"}}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'Types and operators: bad integer, rating out of range, booleans, enums, wrong operators', '{"queries":["price=12.5&rating[gte]=7&rating=4&is_free=yes&level=beginner,expert,pro&price[gt]=5&level[lte]=advanced&price[lte]=99999999999999999999&rating[lte]=4.5&is_free=true"]}', '{"status":400,"errors":["invalid value \"12.5\" for \"price\": expected a whole number","invalid value \"7\" for \"rating\": expected a number from 0 to 5","operator \"eq\" is not allowed on \"rating\"","invalid value \"yes\" for \"is_free\": expected true or false","invalid value \"pro\" for \"level\": expected one of beginner, intermediate, advanced, expert","operator \"gt\" is not allowed on \"price\"","operator \"lte\" is not allowed on \"level\"","invalid value \"99999999999999999999\" for \"price\": expected a whole number","duplicate parameter \"is_free\""]}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'Malformed encoding, bad names, duplicates, a value list where one value is allowed', '{"queries":["is_free=%E0%A4%A&price[lte=5&Level=beginner&price[lte]=5&price[lte]=6&price[gte]=1,2&category=&sort=title&sort=price&&q=%20%20&rating[gte]=4.5"]}', '{"status":400,"errors":["malformed percent-encoding in \"is_free=%E0%A4%A\"","invalid parameter name \"price[lte\"","invalid parameter name \"Level\"","duplicate parameter \"price[lte]\"","\"price[gte]\" takes one value","invalid value \"\" for \"category\": expected 1-40 characters","duplicate parameter \"sort\"","\"q\" must be 1-100 characters"]}', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_232'), 'Sort rules: default order, tie-break direction, unknown, repeated and too many fields', '{"queries":["","sort=title","sort=-price,-published_at","sort=-rating,-rating","sort=rating,title,price,published_at","sort=-id","sort=","level=advanced&sort=price,-title"]}', '"{\"status\":200,\"plan\":{\"filters\":[],\"sort\":[{\"field\":\"published_at\",\"dir\":\"desc\"},{\"field\":\"id\",\"dir\":\"desc\"}],\"q\":null}}\n{\"status\":200,\"plan\":{\"filters\":[],\"sort\":[{\"field\":\"title\",\"dir\":\"asc\"},{\"field\":\"id\",\"dir\":\"asc\"}],\"q\":null}}\n{\"status\":200,\"plan\":{\"filters\":[],\"sort\":[{\"field\":\"price\",\"dir\":\"desc\"},{\"field\":\"published_at\",\"dir\":\"desc\"},{\"field\":\"id\",\"dir\":\"desc\"}],\"q\":null}}\n{\"status\":400,\"errors\":[\"\\\"rating\\\" appears twice in sort\"]}\n{\"status\":400,\"errors\":[\"too many sort fields (max 3)\"]}\n{\"status\":400,\"errors\":[\"cannot sort by \\\"id\\\"\"]}\n{\"status\":400,\"errors\":[\"cannot sort by \\\"\\\"\"]}\n{\"status\":200,\"plan\":{\"filters\":[{\"field\":\"level\",\"op\":\"eq\",\"value\":\"advanced\"}],\"sort\":[{\"field\":\"price\",\"dir\":\"asc\"},{\"field\":\"title\",\"dir\":\"desc\"},{\"field\":\"id\",\"dir\":\"desc\"}],\"q\":null}}"', 3, false, true, 6),
