-- challenge chal_quiz_adp_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_311', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-3-1' AND is_deleted = false LIMIT 1), 'idempotency-keys-quiz', 'Read the payment logs: one key, two charges?', 'Two pieces of evidence from POST /payments: a key check that still charged a double tap twice, and a key reused with a different amount.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311'), 'The first fix for the double charge, in the NestJS PaymentsService:

const found = await this.db.query(
  "SELECT response_status, response_body FROM idempotency_keys WHERE user_id = $1 AND idempotency_key = $2",
  [userId, key]);
if (found.rowCount === 1) return found.rows[0];
const payment = await this.provider.charge(userId, dto);      // takes 1-12 s
await this.db.query(
  "INSERT INTO idempotency_keys (user_id, idempotency_key, response_status, response_body) VALUES ($1, $2, 201, $3)",
  [userId, key, payment]);

API log (a learner double-tapped Buy):
14:02:07.112 POST /payments user=u_17 key=pay-51c0
14:02:07.152 POST /payments user=u_17 key=pay-51c0

Statement: "Because the service looks the key up before charging, these two requests 40 ms apart can only produce one charge."', 'single_choice'::question_type, 'False. This is check-then-act: both requests run the SELECT before either one reaches the INSERT, because the INSERT only happens after a charge that takes seconds. Both see no row, both call provider.charge, and the second INSERT either fails on the primary key or (without a unique key) adds a second row - after the card was charged twice. The fix is to claim the key before doing the work: INSERT a row in state in_progress with ON CONFLICT (user_id, idempotency_key) DO NOTHING, let only the request that inserted it charge, and answer 409 to the one that finds the row still in progress. The misconception is that a lookup is a lock; only a write that the database makes unique decides who goes first.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311'), 'Two requests from the mobile app, one hour apart (a bug in the app reused the key of the previous purchase):

POST /payments  Idempotency-Key: pay-7f3a  {"courseId":"api-design-production","amount":149000}
-> 201 {"paymentId":"pay_9001","amount":149000}

POST /payments  Idempotency-Key: pay-7f3a  {"courseId":"redis-patterns","amount":249000}
-> 201 {"paymentId":"pay_9001","amount":149000}   (replayed from the stored response)

The interceptor looks up the stored response by (user_id, idempotency_key) only.

Statement: "Replaying the stored 201 hides the app''s bug; the server should compare a fingerprint of the request body with the one stored for the key and answer 422."', 'single_choice'::question_type, 'True. The second request is a different purchase: the learner now believes they bought Redis Patterns, but no charge was made and no enrollment exists. An idempotency key promises "the same request again"; it cannot also mean "a different request". Storing a hash of a canonical form of the body (sorted keys, so key order does not matter) and comparing it on every repeat turns this silent wrong answer into an error the app developers will see. The IETF Idempotency-Key draft suggests 422 for a key reused with a different payload. The misconception is that the key alone identifies the request; it only identifies the client''s intent to send one particular request.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_311') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_adp_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_adp_312', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-3-1' AND is_deleted = false LIMIT 1), 'idempotency-key-guard', 'Idempotency guard for POST /payments', 'A learner was charged twice for a course because the CodeDev mobile app retried POST /payments after its 10 s timeout while the first request was still charging the card. The app already sends an Idempotency-Key header and reuses it for every retry of one purchase; the API ignored it. Write IdempotencyGuard, the logic of an interceptor that runs in front of the payments handler. begin(userId, key, body) is called when a request arrives and returns { kind: "run" } (the handler runs and charges), { kind: "replay", status, body } (the stored response; the handler does not run) or { kind: "reject", status, code } (an error; the handler does not run). finish(userId, key, status, body) is called when a handler that was told to run has finished. Rules, in this order: (1) key must be a string of 1 to 255 characters, else reject 400 "idempotency_key_missing"; (2) keys are scoped per user - the same key from two users is two unrelated records; (3) a completed record created ttlMs or more ago (clock.now() - createdAt >= ttlMs) has expired and is forgotten, so the request is treated as new; a record still in progress never expires; (4) no record: create one (in progress, createdAt = now, with the body''s fingerprint) and return run; (5) a record whose fingerprint differs from this body''s: reject 422 "idempotency_key_reused"; (6) same fingerprint, still in progress: reject 409 "idempotency_key_in_progress"; (7) same fingerprint, completed: replay its stored status and body. The fingerprint is a canonical form of the body - object keys sorted at every depth, array order kept - or a sha256 hash of it (node:crypto is available). finish with a status of 500 or more stores nothing and deletes the record, so a retry runs the handler again; any other status (2xx, or 4xx such as 402 card_declined) completes the record with that status and body, and createdAt stays the time of the first request. Use only the injected clock. Input (stdin): { "ttlMs": number, "events": [ { "at", "req", "user", "key"?, "body" } (a request arrives) | { "at", "done", "status", "response" } (that request''s handler finishes) ], "summary"?: true }, in time order. The test runner sets the fake clock to each event''s time, prints one line per event and then the number of times the handler ran (the number of charges), or with summary only the totals. A done event for a request that was not told to run is skipped.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 1, 'Think about the moment the retry arrives while the first request is still charging the card: what must already be written down, at the moment the first request arrived, for the retry to be turned away instead of charging again?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 2, 'Look at three things: what the map key of a record is made of (the user and the idempotency key together), what a record holds besides the response (its state, its createdAt and the fingerprint of the body), and how the fingerprint is computed - JSON.stringify keeps the key order of the object it is given, so two equal payloads can produce different strings unless you sort the keys at every level yourself.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 3, 'A similar guard for POST /enrollments with ttlMs 1000: u_1 sends key e-1 with { "courseId": "c1" } at t=0 -> run; at t=200 the same request -> 409 (still running); the handler finishes at t=300 with 201 -> stored; at t=400 { "courseId": "c1" } -> replayed 201; at t=500 { "courseId": "c2" } -> 422; u_2 with key e-1 at t=600 -> run (a different user); u_1 at t=1000 -> run again, because 1000 - 0 >= ttlMs. If the handler at t=300 had finished with 503 instead, the request at t=400 would run.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'The incident: retries after a slow 201 replay the stored response, the card is charged once', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":12400,"done":"r1","status":201,"response":{"paymentId":"pay_9001","status":"succeeded","amount":149000}},{"at":13000,"req":"r2","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":20000,"req":"r3","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}}]}', '"t=0 r1 u_17 -> handler runs\nt=12400 r1 handler finished 201\nt=13000 r2 u_17 -> 201 replayed {\"paymentId\":\"pay_9001\",\"status\":\"succeeded\",\"amount\":149000}\nt=20000 r3 u_17 -> 201 replayed {\"paymentId\":\"pay_9001\",\"status\":\"succeeded\",\"amount\":149000}\nhandler runs: 1"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'Same key with a different amount is 422, a request without a key is 400', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"pay-1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":900,"done":"r1","status":201,"response":{"paymentId":"pay_9002","status":"succeeded","amount":149000}},{"at":5000,"req":"r2","user":"u_17","key":"pay-1","body":{"courseId":"api-design-production","amount":249000,"currency":"VND","method":"card"}},{"at":6000,"req":"r3","user":"u_17","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":7000,"req":"r4","user":"u_17","key":"pay-2","body":{"courseId":"redis-patterns","amount":249000,"currency":"VND","method":"card"}},{"at":7800,"done":"r4","status":201,"response":{"paymentId":"pay_9003","status":"succeeded","amount":249000}}]}', '"t=0 r1 u_17 -> handler runs\nt=900 r1 handler finished 201\nt=5000 r2 u_17 -> 422 idempotency_key_reused\nt=6000 r3 u_17 -> 400 idempotency_key_missing\nt=7000 r4 u_17 -> handler runs\nt=7800 r4 handler finished 201\nhandler runs: 2"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'A retry while the first request is still running gets 409, then the stored response', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":10000,"req":"r2","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":11000,"req":"r3","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"momo"}},{"at":12400,"done":"r1","status":201,"response":{"paymentId":"pay_9001","status":"succeeded","amount":149000}},{"at":15000,"req":"r4","user":"u_17","key":"pay-7f3a","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":16000,"done":"r2","status":201,"response":{"paymentId":"pay_should_not_exist","status":"succeeded","amount":149000}}]}', '"t=0 r1 u_17 -> handler runs\nt=10000 r2 u_17 -> 409 idempotency_key_in_progress\nt=11000 r3 u_17 -> 422 idempotency_key_reused\nt=12400 r1 handler finished 201\nt=15000 r4 u_17 -> 201 replayed {\"paymentId\":\"pay_9001\",\"status\":\"succeeded\",\"amount\":149000}\nhandler runs: 1"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'Canonical payload: key order does not matter at any depth, array order and nested values do', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"pay-n","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","billing":{"country":"VN","email":"lan@codedev.test","name":"Tran Lan"},"items":[{"id":"c1","qty":1},{"id":"c2","qty":1}]}},{"at":800,"done":"r1","status":201,"response":{"paymentId":"pay_9010","status":"succeeded","amount":149000}},{"at":2000,"req":"r2","user":"u_17","key":"pay-n","body":{"items":[{"qty":1,"id":"c1"},{"qty":1,"id":"c2"}],"billing":{"name":"Tran Lan","email":"lan@codedev.test","country":"VN"},"currency":"VND","amount":149000,"courseId":"api-design-production"}},{"at":3000,"req":"r3","user":"u_17","key":"pay-n","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","billing":{"country":"VN","email":"lan@codedev.test","name":"Tran Lan"},"items":[{"id":"c2","qty":1},{"id":"c1","qty":1}]}},{"at":4000,"req":"r4","user":"u_17","key":"pay-n","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","billing":{"country":"VN","email":"minh@codedev.test","name":"Tran Lan"},"items":[{"id":"c1","qty":1},{"id":"c2","qty":1}]}},{"at":5000,"req":"r5","user":"u_17","key":"pay-n","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","billing":{"country":"VN","email":"lan@codedev.test","name":"Tran Lan"},"items":[{"id":"c1","qty":1},{"id":"c2","qty":2}]}}]}', '"t=0 r1 u_17 -> handler runs\nt=800 r1 handler finished 201\nt=2000 r2 u_17 -> 201 replayed {\"paymentId\":\"pay_9010\",\"status\":\"succeeded\",\"amount\":149000}\nt=3000 r3 u_17 -> 422 idempotency_key_reused\nt=4000 r4 u_17 -> 422 idempotency_key_reused\nt=5000 r5 u_17 -> 422 idempotency_key_reused\nhandler runs: 1"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'Keys are scoped per user: two learners sending the same key each get their own payment', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"retry-1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":700,"done":"r1","status":201,"response":{"paymentId":"pay_a17","status":"succeeded","amount":149000}},{"at":1000,"req":"r2","user":"u_42","key":"retry-1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":1600,"done":"r2","status":201,"response":{"paymentId":"pay_b42","status":"succeeded","amount":149000}},{"at":2000,"req":"r3","user":"u_42","key":"retry-1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":2500,"req":"r4","user":"u_17","key":"retry-1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":3000,"req":"r5","user":"u_99","key":"retry-1","body":{"courseId":"api-design-production","amount":99000,"currency":"VND","method":"card"}},{"at":3400,"done":"r5","status":201,"response":{"paymentId":"pay_c99","status":"succeeded","amount":99000}}]}', '"t=0 r1 u_17 -> handler runs\nt=700 r1 handler finished 201\nt=1000 r2 u_42 -> handler runs\nt=1600 r2 handler finished 201\nt=2000 r3 u_42 -> 201 replayed {\"paymentId\":\"pay_b42\",\"status\":\"succeeded\",\"amount\":149000}\nt=2500 r4 u_17 -> 201 replayed {\"paymentId\":\"pay_a17\",\"status\":\"succeeded\",\"amount\":149000}\nt=3000 r5 u_99 -> handler runs\nt=3400 r5 handler finished 201\nhandler runs: 3"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), 'TTL on the fake clock counts from the first request; a record in progress does not expire', '{"ttlMs":60000,"events":[{"at":0,"req":"r1","user":"u_17","key":"k1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":5000,"done":"r1","status":201,"response":{"paymentId":"pay_1","status":"succeeded","amount":149000}},{"at":59999,"req":"r2","user":"u_17","key":"k1","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":60000,"req":"r3","user":"u_17","key":"k1","body":{"courseId":"api-design-production","amount":249000,"currency":"VND","method":"card"}},{"at":61000,"done":"r3","status":201,"response":{"paymentId":"pay_2","status":"succeeded","amount":249000}},{"at":61500,"req":"r4","user":"u_17","key":"k1","body":{"courseId":"api-design-production","amount":249000,"currency":"VND","method":"card"}},{"at":100000,"req":"r5","user":"u_17","key":"k2","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":170000,"req":"r6","user":"u_17","key":"k2","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":171000,"done":"r5","status":201,"response":{"paymentId":"pay_3","status":"succeeded","amount":149000}},{"at":172000,"req":"r7","user":"u_17","key":"k2","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":200000,"req":"r8","user":"u_17","key":"k3","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":250000,"done":"r8","status":201,"response":{"paymentId":"pay_4","status":"succeeded","amount":149000}},{"at":259999,"req":"r9","user":"u_17","key":"k3","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":260000,"req":"r10","user":"u_17","key":"k3","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":260500,"done":"r10","status":201,"response":{"paymentId":"pay_5","status":"succeeded","amount":149000}}]}', '"t=0 r1 u_17 -> handler runs\nt=5000 r1 handler finished 201\nt=59999 r2 u_17 -> 201 replayed {\"paymentId\":\"pay_1\",\"status\":\"succeeded\",\"amount\":149000}\nt=60000 r3 u_17 -> handler runs\nt=61000 r3 handler finished 201\nt=61500 r4 u_17 -> 201 replayed {\"paymentId\":\"pay_2\",\"status\":\"succeeded\",\"amount\":249000}\nt=100000 r5 u_17 -> handler runs\nt=170000 r6 u_17 -> 409 idempotency_key_in_progress\nt=171000 r5 handler finished 201\nt=172000 r7 u_17 -> handler runs\nt=200000 r8 u_17 -> handler runs\nt=250000 r8 handler finished 201\nt=259999 r9 u_17 -> 201 replayed {\"paymentId\":\"pay_4\",\"status\":\"succeeded\",\"amount\":149000}\nt=260000 r10 u_17 -> handler runs\nt=260500 r10 handler finished 201\nhandler runs: 6"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_adp_312'), '5xx results are not stored and the retry runs again; a 402 is stored; invalid keys are 400', '{"ttlMs":86400000,"events":[{"at":0,"req":"r1","user":"u_17","key":"pay-x","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":3000,"done":"r1","status":503,"response":{"code":"provider_unavailable"}},{"at":4000,"req":"r2","user":"u_17","key":"pay-x","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":4900,"done":"r2","status":500,"response":{"code":"internal_error"}},{"at":6000,"req":"r3","user":"u_17","key":"pay-x","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":6800,"done":"r3","status":201,"response":{"paymentId":"pay_9100","status":"succeeded","amount":149000}},{"at":7000,"req":"r4","user":"u_17","key":"pay-x","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":8000,"req":"r5","user":"u_17","key":"pay-d","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"momo"}},{"at":8600,"done":"r5","status":402,"response":{"code":"card_declined"}},{"at":9000,"req":"r6","user":"u_17","key":"pay-d","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"momo"}},{"at":10000,"req":"r7","user":"u_17","key":"","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":11000,"req":"r8","user":"u_17","key":"kkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkkk","body":{"courseId":"api-design-production","amount":149000,"currency":"VND","method":"card"}},{"at":12000,"req":"r9","user":"u_17","key":"kkkkkkkkkkkk