-- challenge chal_quiz_adp_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_321', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-3-2' AND is_deleted = false LIMIT 1), 'concurrency-etags-quiz', 'Read the edit log: whose change survives?', 'Three pieces of evidence from the course editor: the audit log of a lost description, an UPDATE that matched no row, and a weak ETag sent back in If-Match.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_321'), 'Audit log of course 42 (the editor sends every form field in its PATCH):

09:10:04  GET   /courses/42  user=minh  200  (description = "Learn SQL...")
09:11:40  GET   /courses/42  user=lan   200  (description = "Learn SQL...")
09:14:30  PATCH /courses/42  user=lan   200  {"title":"SQL Basics","description":"Write your first queries...","level":"beginner"}
09:15:02  PATCH /courses/42  user=minh  200  {"title":"SQL Basics for Analysts","description":"Learn SQL...","level":"beginner"}

Each PATCH runs one UPDATE in its own transaction at READ COMMITTED. A teammate proposes switching these transactions to SERIALIZABLE.

Statement: "With SERIALIZABLE transactions, Lan''s new description would have survived Minh''s save."', 'single_choice'::question_type, 'False. The two PATCH transactions are 32 seconds apart and never overlap, so they are already serial: SERIALIZABLE has nothing to detect. The stale value was not read inside a transaction at all - it was read by Minh''s browser at 09:10 and sent back in his PATCH at 09:15. A database transaction cannot span the minutes a person spends in an editor. What protects this read-modify-write is a precondition across the two HTTP requests: the GET returns a version (ETag), the PATCH sends it back in If-Match, and the UPDATE only applies WHERE version = the one the client saw, answering 412 otherwise. The misconception is that a stronger isolation level fixes lost updates that happen between requests.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_321'), 'After the fix, Minh''s editor loaded the course with ETag: "v7" and saves:

PATCH /courses/42
If-Match: "v7"
{"title":"SQL Basics for Analysts","description":"Learn SQL...","level":"beginner"}

The service runs:
UPDATE courses SET title = $2, description = $3, level = $4, version = version + 1
WHERE id = $1 AND version = $5      -- $5 = 7
RETURNING version;
-> UPDATE 0

SELECT version FROM courses WHERE id = 42;  -> 8

