The web client''s submit loop:

for (let attempt = 0; attempt < 5; attempt++) {
  const res = await submit(payload);
  if (res.status !== 429) return res;
  await sleep(1000 * 2 ** attempt);   // 1, 2, 4, 8, 16 s
