-- challenge chal_quiz_adp_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_adp_431', (SELECT id FROM catalog.course WHERE public_id = 'api-design-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'api-design-production') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-adp-4-3' AND is_deleted = false LIMIT 1), 'openapi-versioning-deprecation', 'OpenAPI, versioning and deprecation', 'Three statements on the CodeDev API''s generated OpenAPI document, its versioning policy and the headers of a deprecated field.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431'), '// src/courses/course.dto.ts (the OpenAPI document is generated from these decorators)
export class CourseDto {
  @ApiProperty({ type: "integer", description: "Price in dong" })
  price: number;
}

// src/courses/course.mapper.ts
price: String(row.priceVnd) as unknown as number,   // "web wants a string"

Generated openapi.json:  "price": { "type": "integer", "description": "Price in dong" }
Response of GET /v1/courses/redis-patterns:  { ..., "price": "249000" }

Statement: "Generating the OpenAPI document from the NestJS DTO classes does not prove that responses match it; a test that validates real responses against the generated document would catch this price."', 'single_choice'::question_type, 'True. @nestjs/swagger builds the document from decorators and class metadata, not from what the handler returns at run time. The cast tells TypeScript the string is a number, so neither the compiler nor the generator sees the problem: the document promises an integer and the API sends a string. Code-first generation keeps the document close to the code but does not test it; validating real responses (or responses from the app in memory) against the document closes the gap. The misconception is that a generated spec is correct by construction.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431'), 'docs/api-versioning-policy.md (CodeDev API):
1. The major version is in the URL: /v1/... . A new major version is only for a redesign that cannot be made compatible.
2. Within /v1, additive changes (new endpoints, new optional request fields, new response properties) ship without notice.
3. Breaking changes within /v1 follow expand/contract: deprecate, announce with Deprecation and Sunset headers and a changelog entry, remove after the sunset date (at least 90 days for partner endpoints).

Pull request #530: adds the response property "estimatedHours" (integer) to GET /v1/courses/{slug}.

Statement: "Under this policy, pull request #530 has to wait for /v2 because it changes the response of a /v1 endpoint."', 'single_choice'::question_type, 'False. Rule 2 says new response properties are additive changes that ship within /v1, and for response readers a new property is safe (as long as clients ignore unknown keys, which the policy implies by calling it additive). A new major version is reserved for changes that cannot be made compatible (rule 1). Teams that open /v2 for every change end up running several versions that each need fixes, tests and documentation. The misconception is that any change to a response is a change of version.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431'), '$ curl -sI https://api.codedev.test/v1/courses/api-design-production
HTTP/1.1 200 OK
Content-Type: application/json
Deprecation: @1792746000
Sunset: Mon, 30 Nov 2026 00:00:00 GMT
Link: <https://api.codedev.test/docs/changes/2026-10-course-dto>; rel="deprecation"

Statement: "A client can learn from this response alone that something in it is deprecated (since 23 Oct 2026, 09:00 UTC), the date after which it is expected to stop working, and where to read the migration notice."', 'single_choice'::question_type, 'True. Deprecation (RFC 9745) carries the deprecation date as @ plus Unix seconds: 1792746000 is 23 Oct 2026, 09:00 UTC. Sunset (RFC 8594) carries the date after which the resource or feature is expected to stop working, as an HTTP-date. The Link with rel="deprecation" points to human-readable information. A client library or an API gateway can log or alert on these headers without anyone reading the changelog. The headers do not say which fields are deprecated; that is what the notice and the deprecated flags in the OpenAPI document are for. The misconception is that deprecation only lives in documentation that clients must remember to read.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_adp_431') AND order_index = 3)
    RETURNING id
)
